import {createCase,simulatePayment,investigate,rehearse,approve,applyRepair,verify,checks,COURSE} from './core.mjs';
import {decisionBrief,outcomeFacts} from './story-model.mjs';
import {briefMarkup,factsMarkup,downloadFacts} from './story-components.mjs';
import {esc,conversation} from './customer-shared.mjs';
const root=document.querySelector('#story-app');let s,support,role='merchant',started=false,opened=false,error='';
function reset(scenario='match'){s=simulatePayment(createCase(scenario,'STORY-'+crypto.randomUUID().slice(0,8)));support={messages:[],confirmedAt:null,help:false};started=false;opened=false;error='';role='merchant';render();}
function say(role,text){support.messages.push({id:crypto.randomUUID(),role,text,kind:'message',at:new Date().toISOString()});}
function render(){const b=decisionBrief(s),facts=outcomeFacts(s,support),blocked=s.review?.outcome==='blocked';
root.innerHTML=`<div class="story-toolbar"><div><span class="customer-eyebrow">INTERACTIVE STORY / SAMPLE DATA</span><label style="display:block;margin-top:8px">Choose a story <select id="scenario"><option value="match" ${s.scenario==='match'?'selected':''}>A purchase recovered</option><option value="conflict" ${s.scenario==='conflict'?'selected':''}>A repair correctly refused</option><option value="read-error" ${s.scenario==='read-error'?'selected':''}>Verification needs another check</option></select></label></div><div class="story-tabs" aria-label="Demo perspective"><button data-role="merchant" aria-pressed="${role==='merchant'}">Merchant</button><button data-role="customer" aria-pressed="${role==='customer'}">Customer</button></div><small>Demo controls only. Real customer access stays separate.</small></div>
${!started?`<section class="story-intro"><div><span class="customer-eyebrow">PAYMENT MADE. EXPERIENCE UNFINISHED.</span><h1>The payment succeeded.<br>The customer is still locked out.</h1><blockquote class="story-quote">“I paid yesterday. My course is still locked, and I haven’t heard anything.”</blockquote><p>Illustrative customer scenario. Follow one case from uncertainty to evidence, an approved decision, and a checked outcome.</p><button class="primary" id="start">Follow this recovery →</button></div><div class="story-pair"><div class="story-receipt"><img src="assets/paypal-mark.svg" alt="PayPal" width="28"><small>SAMPLE PAYMENT RECEIPT</small><strong>$128.00 USD · completed</strong><small>${s.scenario==='conflict'?'A completed payment still needs to match the correct order.':'The payment record exists. Access is a separate question.'}</small></div><div class="story-receipt locked"><small>STILLFRAME ACADEMY / DIGITAL COURSE</small><strong>The Light & Story Workshop</strong><p>▤ Your first lesson is locked.</p><small>Payment success alone did not deliver the purchase.</small></div></div></section>`:`<section class="customer-hero"><div class="story-step">${support.confirmedAt?'06 / CUSTOMER CONFIRMATION':b.verified?'05 / CHECKED OUTCOME':blocked?'03 / SAFE REFUSAL':s.approval?'04 / APPROVED CHANGE':s.rehearsal?'03 / MERCHANT DECISION':s.review?'02 / EVIDENCE EXPLAINED':'01 / CUSTOMER WAITING'}</div><h1>${support.confirmedAt?'“It works—thank you.”':blocked?'The safe decision is to stop.':b.verified?'Access checked. Now ask the customer.':role==='customer'?'A purchase you can follow.':'Close the gap. Show the proof.'}</h1><p>${blocked?'This payment belongs to another order. The system refuses an access grant and asks for the matching purchase reference.':support.confirmedAt?'The sample lesson opened, and the customer confirmed success. Two distinct checks, recorded on one case.':'The customer gets updates. The merchant controls the change. The outcome gets its own check.'}</p><span class="status-chip">${role==='merchant'?'Merchant perspective':'Customer perspective'} · browser simulation</span></section>
<div class="story-layout"><section class="customer-card">${role==='merchant'?`<span class="customer-eyebrow">THE DECISION BRIEF</span><h2>Understand the next step.</h2>${briefMarkup(b)}<details><summary>Inspect the purchase checks</summary>${checks(s).map(c=>`<div class="story-check ${c.ok?'':'bad'}"><strong>${c.ok?'✓':'!'} ${esc(c.label)}</strong><p>${esc(c.detail)}</p></div>`).join('')}</details><div class="customer-actions">${!s.review?'<button class="primary" data-action="investigate">Review the evidence</button>':blocked?'<button class="primary" data-action="request">Request the matching order reference</button>':!s.rehearsal?'<button class="primary" data-action="rehearse">Preview the access change</button>':!s.approval?'<label><input id="approve-check" type="checkbox"> I approve one access grant for this purchase.</label><button class="primary" id="approve" data-action="approve" disabled>Approve this correction</button>':!s.writes?'<button class="primary" data-action="repair">Apply approved correction</button>':!s.proof?'<button class="primary" data-action="verify">Verify payment, access & lesson</button>':s.proof&&!s.proof.passed?'<button class="primary" data-action="verify">Retry verification only</button>':'<button class="primary" data-role="customer">See the customer’s outcome →</button>'}</div>${s.rehearsal?'<div class="story-check"><strong>Exact change</strong><p>Course locked → purchased access active.<br>One learner. One course. Existing payment unchanged.</p></div>':''}`:`<span class="customer-eyebrow">YOUR PURCHASE</span><h2>${esc(COURSE.name)}</h2><p>${b.verified?'The sample access check passed. Open the demo lesson and confirm your experience.':blocked?'The merchant needs the order reference for this purchase. No access change has been made.':'The merchant is reviewing the purchase. You can follow the conversation below.'}</p>${b.verified?`<button class="primary" data-action="open">Open my purchase ↗</button>${opened?'<div class="customer-lesson"><strong>01 / See the light</strong><p>Find a window with soft, indirect daylight. Place an everyday object beside it. Make three frames: facing the light, beside it, and against it.</p><small>Local sample lesson. This story does not retrieve the server’s protected content.</small></div><button data-action="confirm" '+(support.confirmedAt?'disabled':'')+'>It works—thank you</button>':''}`:'<div class="story-check">Course access remains locked.</div>'}<form id="customer-message"><label for="story-message">Ask the merchant a question</label><textarea id="story-message" required maxlength="2000" placeholder="What should I try next?"></textarea><button>Send demo message</button></form>`}<p class="story-error" role="alert">${esc(error)}</p></section><aside><section class="customer-card"><span class="customer-eyebrow">ONE CASE / SHARED CONVERSATION</span><h2>No more silence.</h2><div class="customer-thread">${conversation(support.messages)}</div><p class="story-label">Local story messages only. Nothing is emailed.</p></section><section class="customer-card"><span class="customer-eyebrow">OUTCOME RECEIPT</span><h2>Facts you can inspect.</h2>${factsMarkup(facts)}<button id="download">Download measured facts</button>${support.confirmedAt?'<div class="story-confirm">✓ System verified access<br>✓ Customer confirmed success</div><p class="story-ended">Purchase recovery, with proof and communication.</p><button id="blocked-story">Try the case we refuse →</button>':''}</section></aside></div>`}`;
root.querySelector('#scenario').onchange=e=>reset(e.target.value);root.querySelectorAll('[data-role]').forEach(el=>el.onclick=()=>{role=el.dataset.role;render();});root.querySelector('#start')?.addEventListener('click',()=>{started=true;say('customer','I paid, but my course is still locked. Can you help?');say('merchant','We have your request. We’ll check the payment and course access before making a change.');render();});root.querySelector('#approve-check')?.addEventListener('change',e=>root.querySelector('#approve').disabled=!e.target.checked);root.querySelector('#download')?.addEventListener('click',()=>downloadFacts(facts));root.querySelector('#blocked-story')?.addEventListener('click',()=>reset('conflict'));
root.querySelector('#customer-message')?.addEventListener('submit',e=>{e.preventDefault();const text=e.target.querySelector('textarea').value.trim();if(!text)return;say('customer',text);render();});
root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{error='';try{switch(el.dataset.action){case 'investigate':investigate(s);say('automatic',s.review.outcome==='blocked'?'The payment reference does not match this purchase. Access changes are on hold.':'The sample payment matches. The merchant is reviewing a course access correction.');break;case 'rehearse':rehearse(s);break;case 'approve':if(!root.querySelector('#approve-check').checked)return;approve(s,s.rehearsal.id);break;case 'repair':applyRepair(s);say('automatic','The approved access correction was applied. Verification is still pending.');break;case 'verify':verify(s,{paymentAvailable:s.scenario!=='read-error'||s.reads>0,lessonAvailable:s.scenario!=='read-error'||s.reads>0});say('automatic',s.proof.passed?'The simulated payment, entitlement, and lesson check agree. Please open your purchase.':'The access update was recorded, but verification is incomplete. We are checking again; no repeat grant is needed.');break;case 'open':if(!b.verified)throw Error('Access has not been verified.');opened=true;break;case 'confirm':if(!opened||!b.verified)throw Error('Open the verified lesson first.');support.confirmedAt=new Date().toISOString();say('customer','It works—thank you. I can open the lesson now.');break;case 'request':say('merchant','Please provide the order reference from this purchase’s receipt. Do not share passwords or full payment details.');role='customer';break;}}catch(e){error=e.message;}render();});
const thread=root.querySelector('.customer-thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
reset(['match','conflict','read-error'].includes(new URLSearchParams(location.search).get('scenario'))?new URLSearchParams(location.search).get('scenario'):'match');
